INSERT OR IGNORE INTO question_models (id,drill_unit_id,framework_target_id,name,difficulty,description,template,parameter_rules,answer_rules,solution_method,forbidden_features,is_active) VALUES ('a1a-easy-model','a1a','a1a-target-1','A1a_EASY_MODEL','easy','Controlled easy model for Fluent solving.','Create one SAT-style item for the specified target and return one unambiguous answer.','Use direct relationships and reasonable integer values.','The answer must be unique and verifiable by the stated solution method.','Identify the target relationship, solve, and verify.','No unrelated targets, hidden assumptions, trick wording, or unsupported diagrams.',1);
