INSERT OR IGNORE INTO questions (id,domain_id,skill_id,drill_unit_id,framework_target_id,difficulty,question_type,prompt,choices,correct_answer,explanation,question_model_id,source_type,source_question_id,sort_order,status,requires_review,is_gate) VALUES ('g1e-medium-2','geometry-trigonometry','area-and-volume','g1e','g1e-target-2','medium','multiple_choice','A cube''s volume increases by a factor of 64. By what factor did its edge length increase?','["4","8","16","32"]','4','Length uses the cube root of the volume factor: ∛64 = 4.','g1e-medium-model','original','G1-G1E-2',2,'active',0,0);
INSERT OR IGNORE INTO questions (id,domain_id,skill_id,drill_unit_id,framework_target_id,difficulty,question_type,prompt,choices,correct_answer,explanation,question_model_id,source_type,source_question_id,sort_order,status,requires_review,is_gate) VALUES ('g1-gate-1','geometry-trigonometry','area-and-volume','g1a','g1a-target-1','medium','multiple_choice','A circle has diameter 14. What is its area?','["14π","28π","49π","196π"]','49π','The radius is 7, so A = π(7²) = 49π.','g1a-medium-model','original','G1-G1A-1',1,'active',0,1);
INSERT OR IGNORE INTO questions (id,domain_id,skill_id,drill_unit_id,framework_target_id,difficulty,question_type,prompt,choices,correct_answer,explanation,question_model_id,source_type,source_question_id,sort_order,status,requires_review,is_gate) VALUES ('g1-gate-2','geometry-trigonometry','area-and-volume','g1b','g1b-target-2','medium','multiple_choice','A cube has surface area 216. What is its volume?','["36","108","180","216"]','216','6s² = 216 gives s = 6, and 6³ = 216.','g1b-medium-model','original','G1-G1B-2',2,'active',0,1);
INSERT OR IGNORE INTO questions (id,domain_id,skill_id,drill_unit_id,framework_target_id,difficulty,question_type,prompt,choices,correct_answer,explanation,question_model_id,source_type,source_question_id,sort_order,status,requires_review,is_gate) VALUES ('g1-gate-3','geometry-trigonometry','area-and-volume','g1c','g1c-target-2','medium','multiple_choice','A rectangular tank with base 8 by 5 contains 240 cubic units. What is the water height?','["4","6","8","10"]','6','240 = 8(5)h, so h = 6.','g1c-medium-model','original','G1-G1C-3',3,'active',0,1);
INSERT OR IGNORE INTO questions (id,domain_id,skill_id,drill_unit_id,framework_target_id,difficulty,question_type,prompt,choices,correct_answer,explanation,question_model_id,source_type,source_question_id,sort_order,status,requires_review,is_gate) VALUES ('g1-gate-4','geometry-trigonometry','area-and-volume','g1d','g1d-target-4','medium','multiple_choice','Similar solids have a length ratio of 2:3. What is their volume ratio?','["2:3","4:9","6:9","8:27"]','8:27','Cube the length ratio: 2³:3³ = 8:27.','g1d-medium-model','original','G1-G1D-4',4,'active',0,1);
INSERT OR IGNORE INTO questions (id,domain_id,skill_id,drill_unit_id,framework_target_id,difficulty,question_type,prompt,choices,correct_answer,explanation,question_model_id,source_type,source_question_id,sort_order,status,requires_review,is_gate) VALUES ('g1-live-challenge','geometry-trigonometry','area-and-volume','g1e','g1e-target-1','hard','multiple_choice','Two similar square patios have side lengths in a 3:5 ratio. The smaller costs $1,800 to tile at the same rate per square foot. What will the larger patio cost?','["$3,000","$4,200","$5,000","$7,500"]','$5,000','Area scales by (5/3)² = 25/9. Then $1,800 × 25/9 = $5,000.',NULL,'original','G1-G1E-1',1,'active',0,0);
